// Ported from the Node app's Sequelize model HostelAttendance (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class HostelAttendanceConfiguration : IEntityTypeConfiguration<HostelAttendance>
{
    public void Configure(EntityTypeBuilder<HostelAttendance> builder)
    {
        builder.ToTable("hostel_attendance", t =>
        {
            t.HasCheckConstraint("CK_hostel_attendance_status", "[status] IN (N'present', N'absent', N'leave')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired();
        builder.HasIndex(e => new { e.StudentId, e.Date }).IsUnique().HasDatabaseName("uq_hostel_att");
        builder.HasOne(e => e.Student).WithMany(p => p.HostelAttendances).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
